$(document).ready(function () {
    // Ensure Dashmix is loaded before using its helpers
    if (typeof Dashmix !== "undefined" && Dashmix.helpersOnLoad) {
        Dashmix.helpersOnLoad(["jq-validation"]);
    } else {
        console.error(
            "Dashmix is not loaded. Please include Dashmix before this script."
        );
        return;
    }

    // Add custom validator for full month names
    $.validator.addMethod(
        "monthName",
        function (value, element) {
            return (
                this.optional(element) ||
                /^(January|February|March|April|May|June|July|August|September|October|November|December)$/i.test(
                    value
                )
            );
        },
        "Please enter a valid month name."
    );

    // Initialize form validation
    $(".js-validation-month").validate({
        rules: {
            month_name: {
                required: true,
                monthName: true, // Custom rule
            },
            status: {
                required: true,
            },
        },
        messages: {
            month_name: {
                required: "Please enter a month name.",
                monthName: "Please enter a valid full month name.",
            },
            status: {
                required: "Please select a status.",
            },
        },
        errorClass: "is-invalid",
        validClass: "is-valid",
        errorElement: "div",
        highlight: function (element) {
            $(element).addClass("is-invalid").removeClass("is-valid");
        },
        unhighlight: function (element) {
            $(element).addClass("is-valid").removeClass("is-invalid");
        },
        errorPlacement: function (error, element) {
            error.addClass("invalid-feedback");
            if (element.closest(".form-group").length) {
                element.closest(".form-group").append(error);
            } else if (element.closest(".mb-3").length) {
                element.closest(".mb-3").append(error);
            } else {
                element.after(error);
            }
        },
        submitHandler: function (form) {
            form.submit();
        },
        invalidHandler: function (event, validator) {
            if (validator.errorList.length) {
                $(validator.errorList[0].element).focus();
            }
        },
    });

    // Prevent manual submission if invalid
    $(".js-validation-month").on("submit", function (e) {
        if (!$(this).valid()) {
            e.preventDefault();
        }
    });
});
